using System;
using System.IO;
using System.Security.Cryptography;
using System.Text.Json;
using Arkon.Core;

namespace Arkon.Parity
{
    /// <summary>
    /// Replays an oracle generated by the unmodified Godot components, rather
    /// than storing C#-computed expectations. JSON APIs belong only to this
    /// net10 test executable, never to the portable runtime package.
    /// </summary>
    public static class GoldenCases
    {
        private const float Tolerance = .001f;

        public static void Run(Action<bool, string> check)
        {
            var path = Environment.GetEnvironmentVariable("ARKON_GODOT_ORACLE");
            if (string.IsNullOrWhiteSpace(path) || !File.Exists(path))
            {
                check(false, "Godot source parity requires ARKON_GODOT_ORACLE pointing to a freshly generated oracle JSON.");
                return;
            }
            using (var document = JsonDocument.Parse(File.ReadAllText(path)))
            {
                var root = document.RootElement;
                check(root.GetProperty("schema").GetInt32() == 1, "Godot oracle schema is supported.");
                VerifySourceHashes(root.GetProperty("source_files"), check);
                ReplayHealth(root.GetProperty("health"), check);
                var weaponIndex = 0;
                foreach (var trace in root.GetProperty("weapons").EnumerateArray())
                    ReplayWeapon(trace, weaponIndex++, check);
                check(weaponIndex == 2, "Godot oracle includes both finite and infinite ammunition owners.");
                ReplayMovement(root.GetProperty("movement"), check);
            }
        }

        private static void VerifySourceHashes(JsonElement hashes, Action<bool, string> check)
        {
            var addon = FindSourceAddon();
            if (addon == null)
            {
                check(false, "Cannot locate current white_guard/addons/arkon_runtime; set ARKON_GODOT_SOURCE to the Godot project or repository root.");
                return;
            }
            var expectedPaths = new[]
            {
                "combat/health_component.gd", "topdown/weapon_component.gd", "topdown/level3_player.gd",
                "topdown/weapons/pistol.tres", "topdown/weapons/shotgun.tres", "topdown/weapons/bat.tres"
            };
            foreach (var relative in expectedPaths)
            {
                var path = Path.Combine(addon, relative.Replace('/', Path.DirectorySeparatorChar));
                if (!hashes.TryGetProperty(relative, out var expected) || !File.Exists(path))
                {
                    check(false, "Godot oracle is missing its current source input: " + relative);
                    continue;
                }
                using (var sha = SHA256.Create())
                {
                    var actual = Convert.ToHexString(sha.ComputeHash(File.ReadAllBytes(path))).ToLowerInvariant();
                    check(string.Equals(actual, expected.GetString(), StringComparison.OrdinalIgnoreCase),
                        "Godot oracle source SHA-256 matches current file: " + relative);
                }
            }
        }

        private static string FindSourceAddon()
        {
            var supplied = Environment.GetEnvironmentVariable("ARKON_GODOT_SOURCE");
            if (!string.IsNullOrWhiteSpace(supplied)) return AddonAt(Path.GetFullPath(supplied));
            foreach (var start in new[] { Directory.GetCurrentDirectory(), AppContext.BaseDirectory })
            {
                var directory = new DirectoryInfo(start);
                while (directory != null)
                {
                    var addon = AddonAt(directory.FullName);
                    if (addon != null) return addon;
                    directory = directory.Parent;
                }
            }
            return null;
        }

        private static string AddonAt(string root)
        {
            foreach (var candidate in new[]
            {
                Path.Combine(root, "addons", "arkon_runtime"),
                Path.Combine(root, "white_guard", "addons", "arkon_runtime")
            })
                if (Directory.Exists(candidate)) return candidate;
            return null;
        }

        private static void ReplayHealth(JsonElement trace, Action<bool, string> check)
        {
            var initial = trace.GetProperty("initial");
            var model = new HealthModel(initial.GetProperty("maximum").GetInt32(), F(initial, "invulnerability"));
            var changed = 0; var damaged = 0; var deaths = 0; var index = 0;
            model.Changed += (current, maximum) => changed++;
            model.Damaged += (amount, source) => damaged++;
            model.Death += () => deaths++;
            foreach (var step in trace.GetProperty("steps").EnumerateArray())
            {
                var op = step.GetProperty("op").GetString();
                var prefix = "Godot health[" + index++ + "] " + op + ": ";
                var accepted = false;
                switch (op)
                {
                    case "initial": break;
                    case "damage": accepted = model.ApplyDamage(step.GetProperty("amount").GetInt32()); break;
                    case "tick": model.Tick(F(step, "delta")); break;
                    case "heal": model.Heal(step.GetProperty("amount").GetInt32()); break;
                    case "force_kill": accepted = model.ForceKill(); break;
                    case "reset": model.Reset(step.GetProperty("maximum").GetInt32()); break;
                    default: check(false, prefix + "unknown source operation"); continue;
                }
                if (step.TryGetProperty("accepted", out var acceptance))
                    check(accepted == acceptance.GetBoolean(), prefix + "acceptance matches source");
                var state = step.GetProperty("state");
                check(model.Current == state.GetProperty("current").GetInt32()
                    && model.Maximum == state.GetProperty("maximum").GetInt32()
                    && model.Dead == state.GetProperty("dead").GetBoolean(), prefix + "health/maximum/death match source");
                CheckFloat(model.InvulnerabilityRemaining, F(state, "invulnerability"), prefix + "invulnerability", check);
                check(changed == state.GetProperty("changed").GetInt32()
                    && damaged == state.GetProperty("damaged").GetInt32()
                    && deaths == state.GetProperty("deaths").GetInt32(), prefix + "event counts match source");
            }
        }

        private static void ReplayWeapon(JsonElement trace, int ownerIndex, Action<bool, string> check)
        {
            var model = new WeaponModel(trace.GetProperty("infinite").GetBoolean(),
                trace.GetProperty("initial_id").GetString(), trace.GetProperty("initial_ammo").GetInt32());
            var changed = 0; var index = 0;
            model.Changed += (id, ammo) => changed++;
            foreach (var step in trace.GetProperty("steps").EnumerateArray())
            {
                var op = step.GetProperty("op").GetString();
                var prefix = "Godot weapon" + ownerIndex + "[" + index++ + "] " + op + ": ";
                var accepted = false;
                switch (op)
                {
                    case "initial": break;
                    case "shot": accepted = model.ConsumeShot(); break;
                    case "tick": model.Tick(F(step, "delta")); break;
                    case "equip": accepted = model.Equip(step.GetProperty("id").GetString(), step.GetProperty("additional_ammo").GetInt32()); break;
                    default: check(false, prefix + "unknown source operation"); continue;
                }
                if (step.TryGetProperty("accepted", out var acceptance))
                    check(accepted == acceptance.GetBoolean(), prefix + "acceptance matches source");
                var state = step.GetProperty("state");
                check(model.CurrentId == state.GetProperty("id").GetString()
                    && model.Ammo == state.GetProperty("ammo").GetInt32(), prefix + "weapon/ammunition match source");
                CheckFloat(model.Cooldown, F(state, "cooldown"), prefix + "cooldown", check);
                check(changed == state.GetProperty("changed").GetInt32(), prefix + "weapon event count matches source");
                var reserves = state.GetProperty("reserves"); var count = 0; var same = true;
                foreach (var reserve in reserves.EnumerateObject())
                {
                    count++;
                    same &= model.Reserves.TryGetValue(reserve.Name, out var amount) && amount == reserve.Value.GetInt32();
                }
                check(same && model.Reserves.Count == count, prefix + "all per-weapon reserves match source");
            }
        }

        private static void ReplayMovement(JsonElement trace, Action<bool, string> check)
        {
            var motor = new TopdownMotor(); var latch = new InputLatch(); var index = 0;
            foreach (var step in trace.GetProperty("steps").EnumerateArray())
            {
                var prefix = "Godot movement[" + index++ + "]: ";
                motor.ControlsEnabled = step.GetProperty("controls_enabled").GetBoolean();
                motor.CombatEnabled = step.GetProperty("combat_enabled").GetBoolean();
                if (step.TryGetProperty("apply_flashbang", out var flashbang)) motor.ApplyFlashbang(flashbang.GetSingle());
                latch.Sample(V(step.GetProperty("movement")), V(step.GetProperty("aim")),
                    sprintHeld: step.GetProperty("sprint").GetBoolean(), combatEnabled: motor.CombatEnabled);
                motor.Step(latch.Consume(), F(step, "delta"));
                var state = step.GetProperty("state");
                CheckVector(motor.Velocity, V(state.GetProperty("velocity")), prefix + "velocity", check);
                CheckVector(motor.AimDirection, V(state.GetProperty("aim")), prefix + "aim", check);
                CheckFloat(motor.FacingRadians, F(state, "rotation"), prefix + "facing radians", check);
                CheckFloat(motor.FlashbangRemaining, F(state, "flashbang"), prefix + "flashbang", check);
            }
            motor.ControlsEnabled = true;
            motor.CombatEnabled = true;
            latch.Sample(Vec2.Zero, Vec2.Right, actionPressed: true, throwPressed: true);
            var actions = 0; var throws = 0;
            for (var i = 0; i < 3; i++)
            {
                var result = motor.Step(latch.Consume(), 1f / 60);
                if (result.ActionRequested) actions++;
                if (result.ThrowRequested) throws++;
            }
            var edges = trace.GetProperty("edges");
            check(actions == edges.GetProperty("action").GetInt32()
                && throws == edges.GetProperty("throw").GetInt32(), "Godot source one-shot action/throw counts match input-latch/motor requests.");
            // The source's final throwable inventory is not asserted against
            // this motor: inventory belongs to the actor/scene owner adapter.
        }

        private static float F(JsonElement value, string name) => value.GetProperty(name).GetSingle();
        private static Vec2 V(JsonElement value) => new Vec2(value[0].GetSingle(), value[1].GetSingle());
        private static void CheckVector(Vec2 actual, Vec2 expected, string context, Action<bool, string> check) =>
            check(Math.Abs(actual.X - expected.X) <= Tolerance && Math.Abs(actual.Y - expected.Y) <= Tolerance,
                context + " matches source: expected " + expected + ", got " + actual);
        private static void CheckFloat(float actual, float expected, string context, Action<bool, string> check) =>
            check(Math.Abs(actual - expected) <= Tolerance,
                context + " matches source: expected " + expected + ", got " + actual);
    }
}
